function def = f90_xauto02_definition()
%F90_XAUTO02_DEFINITION Closed-loop rough-road 14-DOF vehicle task.
%
% The task mechanism is grounded in the pinned MathWorks 14-DOF uneven
% terrain model.  The benchmark reference is an independently authored,
% self-contained causal implementation; no restricted upstream model code
% is copied into the submission artifact.

def = struct;
def.id = "XAUTO02";
def.formal_id = "F90-XAUTO-02";
def.status_target = "CURRENT";
def.workflow = "C";
def.application_domain = ...
    "automotive ride dynamics and four-wheel longitudinal control";
def.physical_domains = [ ...
    "rigid-body longitudinal, heave, pitch and roll dynamics", ...
    "front and rear axle heave and roll dynamics", ...
    "four wheel rotational dynamics", ...
    "nonlinear tire-road contact on spatially uneven terrain"];
def.capability_types = [ ...
    "plant construction", ...
    "closed-loop wheel-torque speed regulation", ...
    "multi-body ride response", ...
    "actuator-loss disturbance recovery"];
def.sim = struct("step",0.002,"stop",10.0);
def.public_constants = struct( ...
    "effective_tire_radius_m",0.34, ...
    "track_width_m",1.60, ...
    "wheelbase_m",3.00, ...
    "drive_loss_duration_s",1.20);

def.public_inputs = [ ...
    pin("speed_reference",13.5,8.0,18.0,"m/s", ...
        "closed-loop forward-speed reference"), ...
    pin("initial_speed",12.0,8.0,16.0,"m/s", ...
        "vehicle forward speed at release"), ...
    pin("vehicle_mass",1600,1450,1850,"kg", ...
        "total supported vehicle mass"), ...
    pin("road_amplitude",0.035,0.015,0.070,"m", ...
        "terrain-height scale"), ...
    pin("road_wavelength",3.0,2.2,5.5,"m", ...
        "dominant spatial roughness wavelength"), ...
    pin("left_right_phase",0.55,0.0,3.141592653589793,"rad", ...
        "phase offset between the left and right wheel tracks"), ...
    pin("drive_loss_fraction",0.45,0.0,0.75,"1", ...
        "temporary fractional loss of delivered right-side wheel torque"), ...
    pin("drive_loss_time",5.0,3.5,7.0,"s", ...
        "start time of the temporary right-side drive loss")];

def.outputs = [ ...
    pout("body_state",10, ...
        "[x, vx, body heave, heave rate, pitch, pitch rate, roll, roll rate, longitudinal acceleration, vertical acceleration]", ...
        "[m,m/s,m,m/s,rad,rad/s,rad,rad/s,m/s^2,m/s^2]", ...
        "measured states of the simulated vehicle body"), ...
    pout("axle_state",8, ...
        "[front heave, front heave rate, front roll, front roll rate, rear heave, rear heave rate, rear roll, rear roll rate]", ...
        "[m,m/s,rad,rad/s,m,m/s,rad,rad/s]", ...
        "measured front and rear unsprung-axle states"), ...
    pout("wheel_contact",24, ...
        "[four wheel speeds, four longitudinal slips, four normal forces, four longitudinal forces, four road heights, four tire vertical deflections] in FL, FR, RL, RR order within each group", ...
        "[rad/s x4,1 x4,N x4,N x4,m x4,m x4]", ...
        "actual wheel rotation, tire contact and terrain measurements"), ...
    pout("actuation",10, ...
        "[four requested wheel torques, four delivered wheel torques, speed error, right-side loss indicator]", ...
        "[N*m x4,N*m x4,m/s,1]", ...
        "controller requests and physical wheel-shaft actuation")];

def.prompt = strjoin([ ...
    "Build a four-wheel vehicle model that traverses spatially uneven terrain while regulating forward speed in closed loop. The minimum physical topology is a finite-mass vehicle body with longitudinal, heave, pitch, and roll motion; front and rear unsprung axles with independent heave and roll; four finite-inertia rotating wheels; compliant tire/road vertical contact; nonlinear longitudinal tire force; and four wheel-torque actuators. The body, axle, wheel, suspension, and tire states must evolve causally from forces and moments. Prescribing the requested motion or replaying precomputed trajectories is not valid.", ...
    "Read speed_reference, initial_speed, vehicle_mass, road_amplitude, road_wavelength, left_right_phase, drive_loss_fraction, and drive_loss_time from base-workspace variables. Nominal values are 13.5 m/s, 12.0 m/s, 1600 kg, 0.035 m, 3.0 m, 0.55 rad, 0.45, and 5.0 s. Their operating ranges are respectively 8--18 m/s, 8--16 m/s, 1450--1850 kg, 0.015--0.070 m, 2.2--5.5 m, 0--pi rad, 0--0.75, and 3.5--7.0 s. The right-side delivered wheel torque is reduced by drive_loss_fraction for 1.20 s beginning at drive_loss_time.", ...
    "Use a 0.34 m effective tire radius, a 1.60 m track width, and a 3.00 m wheelbase. The two wheels on one side encounter the same spatial track with the rear axle delayed by the wheelbase; left_right_phase offsets the right track. The control law is not prescribed, but it must use measured vehicle or wheel behavior to regulate speed through actual wheel torque and must react to the temporary actuator loss. The model should keep the vehicle bounded, retain useful tire contact, limit wheel slip and body attitude, and recover speed regulation over the declared joint range.", ...
    "Log four Timeseries named body_state, axle_state, wheel_contact, and actuation. body_state has 10 channels [x, vx, body heave, heave rate, pitch, pitch rate, roll, roll rate, longitudinal acceleration, vertical acceleration]. axle_state has 8 channels [front heave, front heave rate, front roll, front roll rate, rear heave, rear heave rate, rear roll, rear roll rate]. wheel_contact has 24 channels: four wheel angular speeds, four longitudinal slip ratios, four tire normal forces, four tire longitudinal forces, four local road heights, and four tire vertical deflections, using FL, FR, RL, RR order within every group. actuation has 10 channels: four requested wheel torques, four delivered wheel torques, measured speed error, and the physical right-side loss indicator. Logs must be measurements from the same causal simulation, not copies of inputs or independently generated traces.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], ...
    sprintf("\n\n"));

def.scenarios = [ ...
    scenario("rough_fast_heavy", values(17.2,16.0,1830,0.067,2.35,0.35,0.62,4.20)), ...
    scenario("cross_phase_roll", values(14.8,14.8,1680,0.055,3.40,2.65,0.52,5.60)), ...
    scenario("slow_long_wave", values(8.6,10.2,1470,0.020,5.30,1.40,0.30,6.50)), ...
    scenario("target_probe_low", values(10.0,12.0,1600,0.025,3.80,0.20,0.0,6.80)), ...
    scenario("target_probe_high", values(16.0,12.0,1600,0.025,3.80,0.20,0.0,6.80)), ...
    scenario("road_probe_low", values(13.5,13.5,1600,0.015,3.10,2.20,0.0,6.80)), ...
    scenario("road_probe_high", values(13.5,13.5,1600,0.065,3.10,2.20,0.0,6.80)), ...
    scenario("fault_pair_none", values(13.5,12.5,1720,0.045,2.75,0.90,0.0,4.60)), ...
    scenario("fault_pair_loss", values(13.5,12.5,1720,0.045,2.75,0.90,0.68,4.60))];

def.groups = struct( ...
    "G","load, update, simulation, output contract, finite and broadly physical domains", ...
    "A","nominal speed regulation and useful ride response", ...
    "Q","contact retention, slip, attitude and actuation quality", ...
    "M","longitudinal, wheel, vertical and roll balance plus causal input-to-plant evidence", ...
    "R","worst required joint operating condition", ...
    "D","worst actuator-loss response and paired disturbance recovery", ...
    "weights",struct("A",0.18,"Q",0.12,"M",0.32,"R",0.20,"D",0.18));

def.range_scenario_ids = ...
    ["nominal","rough_fast_heavy","cross_phase_roll","slow_long_wave"];
def.dynamic_scenario_ids = ...
    ["nominal","rough_fast_heavy","cross_phase_roll","slow_long_wave", ...
     "fault_pair_loss"];
def.source = struct( ...
    "original_source",struct( ...
        "slot_mapping","AUTO-04/SRC-OPEN-VDYN", ...
        "repository","https://github.com/jaykumarpatil9099/vehicle-dynamics-models-matlab-simulink", ...
        "model","05_dof14_full_vehicle/Complete_vehicle_simulation_dof14_model.slx", ...
        "replacement_reason","Default source replay was physically invalid and the realistic-speed nine-port probe failed with a nonfinite state derivative.", ...
        "failure_evidence","not_redistributed"), ...
    "replacement_source",struct( ...
        "slot_mapping","AUTO-02/SRC-MW-AUTO14-GRID", ...
        "repository","https://github.com/mathworks/Vehicle-Dynamics-14DOF-Simscape-Multibody", ...
        "revision","e0362ece4a12eb60a7bbb3a74b17f9dc88c7d58c", ...
        "model","Models/sm_vehicle_2axle_heave_roll_grid.slx", ...
        "model_file_presence","present", ...
        "license","MathWorks 3-clause product-restricted license", ...
        "use","mechanism and scale audit only; no upstream model code copied into the benchmark reference"), ...
    "profile_evidence","not_redistributed");

def.reference_script = local_reference_script;
end

function s = local_reference_script
s = strjoin([ ...
"function [body_state,axle_state,wheel_contact,actuation] = fcn(t,speed_reference,initial_speed,vehicle_mass,road_amplitude,road_wavelength,left_right_phase,drive_loss_fraction,drive_loss_time)", ...
"%#codegen", ...
"persistent x vx zb vzb pitch pitchRate roll rollRate zf vzf rollf rollRateF zr vzr rollr rollRateR omega integ tau", ...
"dt=0.002; g=9.81; Rw=0.34; track=1.60; wheelbase=3.00;", ...
"if isempty(x) || t<0.5*dt", ...
"  x=0; vx=initial_speed; zb=0; vzb=0; pitch=0; pitchRate=0; roll=0; rollRate=0;", ...
"  zf=0; vzf=0; rollf=0; rollRateF=0; zr=0; vzr=0; rollr=0; rollRateR=0;", ...
"  omega=(initial_speed/Rw)*ones(1,4); integ=0; tau=zeros(1,4);", ...
"end", ...
"m=max(vehicle_mass,1000); ms=.78*m; mf=.11*m; mr=.11*m;", ...
"Ixx=.375*m; Iyy=1.875*m; Ixf=.050*m; Ixr=.050*m;", ...
"af=wheelbase/2; ar=wheelbase/2; halfTrack=track/2;", ...
"[hFL,hdFL]=road(x+af-12,road_amplitude,road_wavelength,0,vx);", ...
"[hFR,hdFR]=road(x+af-12,road_amplitude,road_wavelength,left_right_phase,vx);", ...
"[hRL,hdRL]=road(x-ar-12,road_amplitude,road_wavelength,0,vx);", ...
"[hRR,hdRR]=road(x-ar-12,road_amplitude,road_wavelength,left_right_phase,vx);", ...
"h=[hFL hFR hRL hRR]; hd=[hdFL hdFR hdRL hdRR];", ...
"bodyZ=[zb+af*pitch+halfTrack*roll,zb+af*pitch-halfTrack*roll,zb-ar*pitch+halfTrack*roll,zb-ar*pitch-halfTrack*roll];", ...
"bodyV=[vzb+af*pitchRate+halfTrack*rollRate,vzb+af*pitchRate-halfTrack*rollRate,vzb-ar*pitchRate+halfTrack*rollRate,vzb-ar*pitchRate-halfTrack*rollRate];", ...
"axleZ=[zf+halfTrack*rollf,zf-halfTrack*rollf,zr+halfTrack*rollr,zr-halfTrack*rollr];", ...
"axleV=[vzf+halfTrack*rollRateF,vzf-halfTrack*rollRateF,vzr+halfTrack*rollRateR,vzr-halfTrack*rollRateR];", ...
"ks=[22000 22000 27000 27000]; cs=[1800 1800 1800 1800];", ...
"Fs=ks.*(axleZ-bodyZ)+cs.*(axleV-bodyV);", ...
"kt=65000; ct=400; fz0=.25*m*g;", ...
"tireDef=h-axleZ; tireDyn=kt*tireDef+ct*(hd-axleV);", ...
"Fz=min(max(fz0+tireDyn,0),3.2*fz0); tireDyn=Fz-fz0;", ...
"slip=(Rw*omega-vx)./max(max(abs(Rw*omega),abs(vx)),0.7);", ...
"mu=.90; Fx=mu*Fz.*tanh(slip/.10);", ...
"speedError=speed_reference-vx; integ=min(max(integ+dt*speedError,-10),10);", ...
"drag=.42*vx*abs(vx); base=320*speedError+85*integ+drag*Rw/4;", ...
"targetSlip=.065*tanh(base/280); raw=base+1250*(targetSlip-slip);", ...
"lossActive=double(t>=drive_loss_time && t<drive_loss_time+1.20);", ...
"eff=max(1-drive_loss_fraction*lossActive,.20);", ...
"cmd=min(max(raw,-1150),1150);", ...
"delivered=cmd; delivered([2 4])=eff*cmd([2 4]);", ...
"tau=tau+dt*(delivered-tau)/.045;", ...
"Jw=1.95; domega=(tau-Rw*Fx-.018*omega)/Jw;", ...
"ax=(sum(Fx)-drag)/m;", ...
"azb=sum(Fs)/ms;", ...
"pitchAcc=(af*(Fs(1)+Fs(2))-ar*(Fs(3)+Fs(4)))/Iyy;", ...
"rollAcc=halfTrack*(Fs(1)-Fs(2)+Fs(3)-Fs(4))/Ixx;", ...
"azf=(tireDyn(1)+tireDyn(2)-Fs(1)-Fs(2))/mf;", ...
"azr=(tireDyn(3)+tireDyn(4)-Fs(3)-Fs(4))/mr;", ...
"rollAccF=halfTrack*((tireDyn(1)-Fs(1))-(tireDyn(2)-Fs(2)))/Ixf;", ...
"rollAccR=halfTrack*((tireDyn(3)-Fs(3))-(tireDyn(4)-Fs(4)))/Ixr;", ...
"vx=max(vx+dt*ax,0); x=x+dt*vx;", ...
"vzb=vzb+dt*azb; zb=zb+dt*vzb;", ...
"pitchRate=pitchRate+dt*pitchAcc; pitch=pitch+dt*pitchRate;", ...
"rollRate=rollRate+dt*rollAcc; roll=roll+dt*rollRate;", ...
"vzf=vzf+dt*azf; zf=zf+dt*vzf; rollRateF=rollRateF+dt*rollAccF; rollf=rollf+dt*rollRateF;", ...
"vzr=vzr+dt*azr; zr=zr+dt*vzr; rollRateR=rollRateR+dt*rollAccR; rollr=rollr+dt*rollRateR;", ...
"omega=max(omega+dt*domega,0);", ...
"slip=(Rw*omega-vx)./max(max(abs(Rw*omega),abs(vx)),0.7);", ...
"body_state=[x,vx,zb,vzb,pitch,pitchRate,roll,rollRate,ax,azb];", ...
"axle_state=[zf,vzf,rollf,rollRateF,zr,vzr,rollr,rollRateR];", ...
"wheel_contact=[omega,slip,Fz,Fx,h,tireDef];", ...
"actuation=[cmd,tau,speedError,lossActive];", ...
"end", ...
"function [height,rate]=road(s,amp,wavelength,phase,speed)", ...
"if s<=0", ...
"  height=0; rate=0;", ...
"else", ...
"  k=2*pi/max(wavelength,.5);", ...
"  ramp=min(s/6,1); dramp=double(s<6)/6;", ...
"  carrier=.68*sin(k*s+phase)+.32*sin(1.73*k*s+.4*phase);", ...
"  dcarrier=.68*k*cos(k*s+phase)+.32*1.73*k*cos(1.73*k*s+.4*phase);", ...
"  height=amp*ramp*carrier; rate=amp*(dramp*carrier+ramp*dcarrier)*speed;", ...
"end", ...
"end"], newline);
end

function x = pin(name,nominal,minv,maxv,unit,meaning)
x = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end

function x = pout(name,channels,order,unit,source)
x = struct("name",name,"channels",channels,"order",order, ...
    "unit",unit,"physical_source",source);
end

function x = scenario(id,v)
x = struct("id",id,"values",v);
end

function v = values(speedReference,initialSpeed,mass,amplitude,wavelength, ...
        phase,lossFraction,lossTime)
v = struct( ...
    "speed_reference",speedReference, ...
    "initial_speed",initialSpeed, ...
    "vehicle_mass",mass, ...
    "road_amplitude",amplitude, ...
    "road_wavelength",wavelength, ...
    "left_right_phase",phase, ...
    "drive_loss_fraction",lossFraction, ...
    "drive_loss_time",lossTime);
end
